<script setup>
import { computed, ref } from 'vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
const props = defineProps({ organization: Object, currentBranch: Object, orders: Object, suppliers: Array, products: Array, canManagePurchases: Boolean, flashMessage: String, errorMessage: String });
const makeLine = (excludedIds = []) => { const p = props.products.find(candidate => !excludedIds.includes(String(candidate.id))) ?? props.products[0]; const u = p?.units?.[0]; return { product_id: p ? String(p.id) : '', unit_id: u ? String(u.id) : '', quantity: '1.000', unit_cost: u?.purchasePrice ?? p?.purchasePrice ?? '0.00' }; };
const form = useForm({ supplier_id: props.suppliers[0] ? String(props.suppliers[0].id) : '', expected_at: '', notes: '', items: [makeLine()] });
const receivingOrderId = ref(null);
const receiveForm = useForm({ supplier_invoice_number: '', paid_amount: '0.00', notes: '', items: [] });
const selectedOrder = computed(() => props.orders.data?.find(o => Number(o.id) === Number(receivingOrderId.value)) ?? null);
const productFor = (line) => props.products.find(p => Number(p.id) === Number(line.product_id));
const unitFor = (line) => productFor(line)?.units?.find(u => Number(u.id) === Number(line.unit_id));
const money = (v) => `${Number(v ?? 0).toLocaleString('ar-EG', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ${props.organization.currency ?? 'EGP'}`;
const total = computed(() => form.items.reduce((sum, item) => sum + Math.max(0, Number(item.quantity) || 0) * Math.max(0, Number(item.unit_cost) || 0), 0));
const lineTotal = (line) => ((Math.max(0, Number(line.quantity) || 0) * Math.max(0, Number(line.unit_cost) || 0)).toFixed(2));
function changeProduct(line) { const p = productFor(line); const u = p?.units?.[0]; line.unit_id = u ? String(u.id) : ''; line.unit_cost = u?.purchasePrice ?? p?.purchasePrice ?? '0.00'; }
function changeUnit(line) { const u = unitFor(line); if (u?.purchasePrice !== undefined) line.unit_cost = String(u.purchasePrice); }
function addLine() { if (form.items.length < Math.min(100, props.products.length)) form.items.push(makeLine(form.items.map(line => String(line.product_id)))); }
function removeLine(i) { if (form.items.length > 1) form.items.splice(i, 1); }
function submitOrder() { form.post('/purchase-orders', { preserveScroll: true, onSuccess: () => { form.reset(); form.supplier_id = props.suppliers[0] ? String(props.suppliers[0].id) : ''; form.expected_at = ''; form.notes = ''; form.items = [makeLine()]; } }); }
function startReceiving(order) { receivingOrderId.value = order.id; receiveForm.clearErrors(); receiveForm.supplier_invoice_number = ''; receiveForm.paid_amount = '0.00'; receiveForm.notes = ''; receiveForm.items = order.items.filter(i => Number(i.quantityRemaining) > 0).map(i => ({ order_item_id: i.id, name: i.name, sku: i.sku, unit_name: i.unitName, remaining: i.quantityRemaining, quantity: i.quantityRemaining })); }
function submitReceipt() { if (!receivingOrderId.value) return; receiveForm.transform(data => ({ ...data, items: data.items.map(i => ({ order_item_id: i.order_item_id, quantity: i.quantity })) })).post(`/purchase-orders/${receivingOrderId.value}/receive`, { preserveScroll: true, onSuccess: () => { receivingOrderId.value = null; receiveForm.reset(); } }); }
function cancelOrder(order) { if (window.confirm(`إلغاء أمر الشراء ${order.orderNumber}؟`)) router.post(`/purchase-orders/${order.id}/cancel`, {}, { preserveScroll: true }); }
const statusText = (s) => ({ ordered: 'مُرسل للمورد', partially_received: 'استلام جزئي', received: 'مستلم بالكامل', cancelled: 'ملغي' })[s] ?? s;
const statusClass = (s) => ({ ordered: 'border-sky-300/20 bg-sky-300/10 text-sky-200', partially_received: 'border-amber-300/20 bg-amber-300/10 text-amber-200', received: 'border-emerald-300/20 bg-emerald-300/10 text-emerald-200', cancelled: 'border-rose-300/20 bg-rose-300/10 text-rose-200' })[s] ?? 'border-white/10 bg-white/5 text-slate-300';
</script>
<template>
  <Head title="أوامر الشراء" />
  <div dir="rtl" class="min-h-screen bg-slate-950 text-slate-100">
    <header class="border-b border-white/10 bg-slate-900/80"><div class="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-4 px-5 py-4"><div><p class="font-black tracking-wide">METRIK <span class="text-emerald-300">POS</span></p><p class="mt-1 text-sm text-slate-400">{{ organization.name }} · {{ currentBranch.name }}</p></div><nav class="flex flex-wrap gap-2 text-sm font-semibold"><Link href="/purchase-invoices" class="rounded-xl border border-white/10 px-4 py-2">فواتير الشراء</Link><Link href="/suppliers" class="rounded-xl border border-white/10 px-4 py-2">الموردون</Link><Link href="/products" class="rounded-xl border border-white/10 px-4 py-2">المنتجات</Link><Link href="/dashboard" class="rounded-xl border border-white/10 px-4 py-2">لوحة التحكم</Link></nav></div></header>
    <main class="mx-auto max-w-7xl space-y-6 px-4 py-6 sm:px-6">
      <div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-sm font-bold text-emerald-300">المشتريات والموردون</p><h1 class="mt-1 text-3xl font-black">أوامر الشراء</h1><p class="mt-2 text-sm text-slate-400">أنشئ الأمر أولًا، ثم سجّل كل استلام فعلي. إنشاء الأمر لا يغيّر المخزون.</p></div><div class="rounded-2xl border border-white/10 bg-white/[0.03] px-4 py-3"><span class="text-sm text-slate-400">عدد الأوامر</span><p class="mt-1 text-xl font-black">{{ orders.total ?? orders.data?.length ?? 0 }}</p></div></div>
      <div v-if="flashMessage" class="rounded-xl border border-emerald-300/20 bg-emerald-300/10 p-4 text-sm text-emerald-100">{{ flashMessage }}</div><div v-if="errorMessage" class="rounded-xl border border-rose-300/20 bg-rose-300/10 p-4 text-sm text-rose-100">{{ errorMessage }}</div>
      <section v-if="canManagePurchases" class="rounded-2xl border border-white/10 bg-slate-900/70 p-5 shadow-xl sm:p-6"><div class="mb-5 flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-xl font-black">إنشاء أمر شراء</h2><p class="mt-1 text-sm text-slate-400">تُحفظ وحدة الشراء ومعامل التحويل والسعر في الأمر.</p></div><span class="rounded-full border border-emerald-300/20 bg-emerald-300/10 px-3 py-1 text-xs font-bold text-emerald-200">بدون حركة مخزون</span></div>
        <form class="space-y-5" @submit.prevent="submitOrder"><div class="grid gap-4 md:grid-cols-3"><div><label class="mb-2 block text-sm font-semibold">المورد *</label><select v-model="form.supplier_id" required class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3"><option v-for="s in suppliers" :key="s.id" :value="String(s.id)">{{ s.name }}{{ s.code ? ` · ${s.code}` : '' }}</option></select><p v-if="form.errors.supplier_id" class="mt-1 text-sm text-rose-300">{{ form.errors.supplier_id }}</p></div><div><label class="mb-2 block text-sm font-semibold">تاريخ الاستلام المتوقع</label><input v-model="form.expected_at" type="date" class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3" /></div><div><label class="mb-2 block text-sm font-semibold">ملاحظات</label><input v-model="form.notes" maxlength="3000" class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3" placeholder="اختياري" /></div></div>
          <div class="space-y-3"><div class="flex items-center justify-between"><h3 class="font-bold">الأصناف المطلوبة</h3><button type="button" @click="addLine" :disabled="form.items.length >= Math.min(100, products.length) || !products.length" class="rounded-lg border border-white/10 px-3 py-2 text-sm font-bold disabled:opacity-40">+ إضافة صنف</button></div>
            <div v-for="(line, index) in form.items" :key="index" class="grid gap-3 rounded-xl border border-white/10 bg-slate-950/70 p-3 md:grid-cols-[2fr_1.2fr_.7fr_.9fr_.9fr_auto] md:items-end"><div><label class="mb-1 block text-xs text-slate-400">المنتج</label><select v-model="line.product_id" required @change="changeProduct(line)" class="w-full rounded-lg border border-white/10 bg-slate-900 px-3 py-2.5 text-sm"><option v-for="p in products" :key="p.id" :value="String(p.id)">{{ p.name }} · {{ p.sku }}</option></select></div><div><label class="mb-1 block text-xs text-slate-400">وحدة الشراء</label><select v-model="line.unit_id" required @change="changeUnit(line)" class="w-full rounded-lg border border-white/10 bg-slate-900 px-3 py-2.5 text-sm"><option v-for="u in (productFor(line)?.units ?? [])" :key="u.id" :value="String(u.id)">{{ u.unitName }} (×{{ u.factorToBase }})</option></select></div><div><label class="mb-1 block text-xs text-slate-400">الكمية</label><input v-model="line.quantity" required type="number" min="0.001" step="0.001" max="100000" class="w-full rounded-lg border border-white/10 bg-slate-900 px-3 py-2.5 text-sm" /></div><div><label class="mb-1 block text-xs text-slate-400">سعر الوحدة</label><input v-model="line.unit_cost" required type="number" min="0" step="0.01" class="w-full rounded-lg border border-white/10 bg-slate-900 px-3 py-2.5 text-sm" /></div><div><label class="mb-1 block text-xs text-slate-400">الإجمالي</label><div class="rounded-lg border border-white/5 bg-white/[0.03] px-3 py-2.5 text-sm font-bold">{{ money(lineTotal(line)) }}</div></div><button type="button" @click="removeLine(index)" :disabled="form.items.length <= 1" class="rounded-lg border border-rose-300/20 px-3 py-2.5 text-sm font-bold text-rose-200 disabled:opacity-30">حذف</button></div>
            <p v-if="form.errors.items" class="text-sm text-rose-300">{{ form.errors.items }}</p></div>
          <div class="flex flex-wrap items-center justify-between gap-3 border-t border-white/10 pt-4"><div><p class="text-sm text-slate-400">إجمالي الأمر التقديري</p><p class="mt-1 text-2xl font-black text-emerald-200">{{ money(total) }}</p></div><button type="submit" :disabled="form.processing || !suppliers.length || !products.length" class="rounded-xl bg-emerald-300 px-5 py-3 font-black text-slate-950 disabled:opacity-50">{{ form.processing ? 'جارٍ الحفظ...' : 'إنشاء أمر الشراء' }}</button></div></form>
      </section>
      <section class="space-y-4"><div><h2 class="text-xl font-black">الأوامر السابقة</h2><p class="mt-1 text-sm text-slate-400">كل دفعة استلام تُسجل كفاتورة شراء مستقلة.</p></div><div v-if="!orders.data?.length" class="rounded-2xl border border-dashed border-white/15 p-8 text-center text-slate-400">لا توجد أوامر شراء حتى الآن.</div>
        <article v-for="order in orders.data" :key="order.id" class="rounded-2xl border border-white/10 bg-slate-900/60 p-4 sm:p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div><div class="flex flex-wrap items-center gap-2"><h3 class="text-lg font-black">{{ order.orderNumber }}</h3><span class="rounded-full border px-3 py-1 text-xs font-bold" :class="statusClass(order.status)">{{ statusText(order.status) }}</span></div><p class="mt-1 text-sm text-slate-300">{{ order.supplier?.name ?? 'مورد محذوف' }} · {{ order.orderedAt ?? '—' }}</p><p v-if="order.expectedAt" class="mt-1 text-xs text-slate-400">الاستلام المتوقع: {{ order.expectedAt }}</p></div><div class="text-left"><p class="text-xs text-slate-400">قيمة الأمر</p><p class="mt-1 text-lg font-black">{{ money(order.subtotal) }}</p></div></div>
          <div class="mt-4 overflow-x-auto"><table class="w-full min-w-[650px] text-right text-sm"><thead class="text-xs text-slate-400"><tr class="border-b border-white/10"><th class="px-2 py-2">الصنف</th><th class="px-2 py-2">الوحدة</th><th class="px-2 py-2">المطلوب</th><th class="px-2 py-2">المستلم</th><th class="px-2 py-2">المتبقي</th><th class="px-2 py-2">قيمة الصنف</th></tr></thead><tbody><tr v-for="item in order.items" :key="item.id" class="border-b border-white/5 last:border-0"><td class="px-2 py-3"><span class="font-semibold">{{ item.name }}</span><span class="block text-xs text-slate-500">{{ item.sku }}</span></td><td class="px-2 py-3">{{ item.unitName }}</td><td class="px-2 py-3">{{ item.quantityOrdered }}</td><td class="px-2 py-3">{{ item.quantityReceived }}</td><td class="px-2 py-3 font-bold" :class="Number(item.quantityRemaining) > 0 ? 'text-amber-200' : 'text-emerald-200'">{{ item.quantityRemaining }}</td><td class="px-2 py-3">{{ money(item.lineTotal) }}</td></tr></tbody></table></div>
          <div v-if="order.receipts?.length" class="mt-3 flex flex-wrap gap-2 text-xs text-slate-400"><span class="font-bold">فواتير الاستلام:</span><span v-for="receipt in order.receipts" :key="receipt.id" class="rounded-lg border border-white/10 px-2 py-1">{{ receipt.invoiceNumber }} · {{ money(receipt.total) }}</span></div>
          <div v-if="canManagePurchases && ['ordered', 'partially_received'].includes(order.status)" class="mt-4 flex flex-wrap justify-end gap-2 border-t border-white/10 pt-4"><button type="button" @click="startReceiving(order)" class="rounded-xl bg-emerald-300 px-4 py-2.5 text-sm font-black text-slate-950">تسجيل استلام</button><button v-if="order.status === 'ordered'" type="button" @click="cancelOrder(order)" class="rounded-xl border border-rose-300/20 px-4 py-2.5 text-sm font-bold text-rose-200">إلغاء الأمر</button></div>
        </article>
        <div v-if="orders.links?.length > 3" class="flex flex-wrap gap-2"><Link v-for="link in orders.links" :key="link.label" :href="link.url ?? '#'" preserve-scroll class="rounded-lg border border-white/10 px-3 py-2 text-sm" :class="{ 'border-emerald-300/40 bg-emerald-300/10 text-emerald-200': link.active, 'pointer-events-none opacity-40': !link.url }" v-html="link.label" /></div>
      </section>
      <section v-if="receivingOrderId && selectedOrder" class="fixed inset-0 z-50 flex items-end justify-center bg-black/70 p-2 sm:items-center sm:p-4" @click.self="receivingOrderId = null"><div class="max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-2xl border border-white/10 bg-slate-900 p-5 shadow-2xl sm:p-6"><div class="flex items-start justify-between gap-3"><div><h2 class="text-xl font-black">استلام أمر {{ selectedOrder.orderNumber }}</h2><p class="mt-1 text-sm text-slate-400">أدخل الكمية التي وصلت فعلًا ولا تتجاوز المتبقي.</p></div><button type="button" @click="receivingOrderId = null" class="rounded-lg border border-white/10 px-3 py-2">إغلاق</button></div>
        <form class="mt-5 space-y-4" @submit.prevent="submitReceipt"><div class="grid gap-3 md:grid-cols-3"><div><label class="mb-1 block text-sm">رقم فاتورة المورد</label><input v-model="receiveForm.supplier_invoice_number" maxlength="120" class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-2.5" /></div><div><label class="mb-1 block text-sm">المدفوع الآن</label><input v-model="receiveForm.paid_amount" type="number" min="0" step="0.01" required class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-2.5" /><p v-if="receiveForm.errors.paid_amount" class="mt-1 text-xs text-rose-300">{{ receiveForm.errors.paid_amount }}</p></div><div><label class="mb-1 block text-sm">ملاحظات الاستلام</label><input v-model="receiveForm.notes" maxlength="3000" class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-2.5" /></div></div>
          <div v-for="item in receiveForm.items" :key="item.order_item_id" class="grid gap-3 rounded-xl border border-white/10 bg-slate-950/70 p-3 sm:grid-cols-[1fr_130px_130px] sm:items-center"><div><p class="font-bold">{{ item.name }}</p><p class="mt-1 text-xs text-slate-400">{{ item.sku }} · {{ item.unit_name }} · المتبقي {{ item.remaining }}</p></div><div><label class="mb-1 block text-xs text-slate-400">الكمية المستلمة</label><input v-model="item.quantity" type="number" min="0" step="0.001" :max="item.remaining" class="w-full rounded-lg border border-white/10 bg-slate-900 px-3 py-2.5" /></div><div class="text-xs text-slate-400">الحد الأقصى: <span class="font-bold text-slate-200">{{ item.remaining }}</span></div></div>
          <p v-if="receiveForm.errors.items" class="text-sm text-rose-300">{{ receiveForm.errors.items }}</p><p v-if="receiveForm.errors.order" class="text-sm text-rose-300">{{ receiveForm.errors.order }}</p><div class="flex justify-end gap-2 border-t border-white/10 pt-4"><button type="button" @click="receivingOrderId = null" class="rounded-xl border border-white/10 px-4 py-2.5">إلغاء</button><button type="submit" :disabled="receiveForm.processing || !receiveForm.items.length" class="rounded-xl bg-emerald-300 px-5 py-2.5 font-black text-slate-950 disabled:opacity-50">{{ receiveForm.processing ? 'جارٍ التسجيل...' : 'تأكيد الاستلام وتحديث المخزون' }}</button></div></form>
      </div></section>
    </main>
  </div>
</template>
